CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE brand_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),brand_id text NOT NULL,version integer NOT NULL CHECK(version>0),profile jsonb NOT NULL,active boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(brand_id,version));
CREATE TABLE content_briefs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key text UNIQUE NOT NULL,source_event_id text NOT NULL,campaign_id text NOT NULL,topic_id text NOT NULL,brand_id text NOT NULL,brand_version integer NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'accepted',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE brief_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),brief_id uuid NOT NULL REFERENCES content_briefs(id),evidence_id text NOT NULL,title text NOT NULL,summary text NOT NULL,source_url text,evidence_type text NOT NULL CHECK(evidence_type IN('simulated','source_verified')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(brief_id,evidence_id));
CREATE TABLE content_packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),package_key text NOT NULL,brief_id uuid NOT NULL REFERENCES content_briefs(id),version integer NOT NULL CHECK(version>0),fingerprint text NOT NULL,status text NOT NULL CHECK(status IN('generated','qa_failed','needs_review','approved','rejected','export_ready','released','archived')),brand_id text NOT NULL,brand_version integer NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(package_key,version));
CREATE TABLE content_variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),package_id uuid NOT NULL REFERENCES content_packages(id),format text NOT NULL CHECK(format IN('article','reel_script','carousel','email','short_video_script')),payload jsonb NOT NULL,fingerprint text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(package_id,format));
CREATE TABLE claim_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),package_id uuid NOT NULL REFERENCES content_packages(id),claim_id text NOT NULL,claim_text text NOT NULL,kind text NOT NULL,evidence_ids jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(package_id,claim_id));
CREATE TABLE qa_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),package_id uuid NOT NULL REFERENCES content_packages(id),engine_version text NOT NULL,passed boolean NOT NULL,summary jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE qa_findings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),qa_run_id uuid NOT NULL REFERENCES qa_runs(id),code text NOT NULL,severity text NOT NULL CHECK(severity IN('error','review','warning')),details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE review_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),package_id uuid NOT NULL REFERENCES content_packages(id),package_version integer NOT NULL,role text NOT NULL CHECK(role IN('brand_reviewer','factual_reviewer','legal_reviewer')),actor text NOT NULL,status text NOT NULL CHECK(status IN('approved','rejected')),note text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(package_id,package_version,role));
CREATE TABLE export_manifests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),package_id uuid NOT NULL REFERENCES content_packages(id),package_version integer NOT NULL,manifest jsonb NOT NULL,fingerprint text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(package_id,package_version));
CREATE TABLE delivery_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),export_manifest_id uuid REFERENCES export_manifests(id),attempt_number integer NOT NULL,status text NOT NULL,error_code text,next_retry_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(export_manifest_id,attempt_number));
CREATE TABLE dead_letter_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL,entity_id uuid,reason text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id bigserial PRIMARY KEY,entity_type text NOT NULL,entity_id uuid,actor text NOT NULL,action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_briefs_campaign ON content_briefs(campaign_id,created_at DESC);CREATE INDEX idx_packages_review ON content_packages(status,updated_at);CREATE INDEX idx_findings_code ON qa_findings(code,severity);
